sys_ui_action.client_script_v2:
function onClick(g_form) {
    console.log('[CALLBACK CLIENT] UI Action clicked successfully.');

    var contactId = g_form.getValue('contact') || '';
    var consumerId = g_form.getValue('consumer') || '';
    var contextQuery = contactId ? 'contact=' + contactId : (consumerId ? 'consumer=' + consumerId : '');

    var openModal = function(defaultPhone) {
        g_modal.showFields({
            title: 'Create Callback Task',
            size: 'lg',
            fields: [
                { type: 'choice', name: 'reason', label: 'Reason for the call', mandatory: true,
                  choices: [
                      { value: 'product_issue', displayValue: 'Product Issue' },
                      { value: 'order_issue', displayValue: 'Order Issue' },
                      { value: 'billing_issue', displayValue: 'Billing Issue' },
                      { value: 'other', displayValue: 'Other Issue' }
                  ]
                },
                { type: 'string', name: 'details', label: 'Callback Reason Details' },
                { type: 'string', name: 'phone', label: 'Callback number', mandatory: true, value: defaultPhone },
                { type: 'reference', name: 'context', label: 'Callback Context', reference: 'sn_customerservice_case', sysparm_query: contextQuery }
            ]
        }).then(function(result) {
            console.log('[CALLBACK CLIENT] Modal submitted. Extracting values securely...');
            g_form.addInfoMessage('Invoking backend subflow logic pipeline...');

            var getVal = function(name, defaultValue) {
                if (result && result.updatedFields) {
                    var field = result.updatedFields.filter(function(f) { return f.name === name; })[0];
                    if (field) return field.value;
                }
                return defaultValue || '';
            };

            var selectedReason = getVal('reason', 'product_issue');
            var selectedDetails = getVal('details', '');
            var selectedPhone = getVal('phone', defaultPhone);
            var selectedContext = getVal('context', '');
            var interactionSysId = g_form.getUniqueValue();

            console.log('[CALLBACK CLIENT] Sending to server -> Interaction: ' + interactionSysId + ' | Phone: ' + selectedPhone + ' | Reason: ' + selectedReason);

            // FIX: Pointing GlideAjax directly to your updated Toolkit scope and script name
            var ga = new GlideAjax('x_snc_pab_ee_tkit.CallbackRecordCreation');
            ga.addParam('sysparm_name', 'executeCallbackSubflow');
            ga.addParam('sysparm_interaction', interactionSysId);
            ga.addParam('sysparm_reason', selectedReason);
            ga.addParam('sysparm_details', selectedDetails);
            ga.addParam('sysparm_phone', selectedPhone);
            ga.addParam('sysparm_context', selectedContext);

            ga.getXMLAnswer(function(response) {
                g_form.clearMessages();
                console.log('[CALLBACK CLIENT] Server transaction response returned: ' + response);

                try {
                    if (!response) {
                        g_form.addErrorMessage('Received empty response from the server script.');
                        return;
                    }
                    var parsed = JSON.parse(response);
                    if (parsed && parsed.status === 'success') {
                        g_form.addInfoMessage(parsed.notes ? 'Callback task processed: ' + parsed.notes : 'Callback activity created successfully.');
                        g_form.reload();
                    } else {
                        g_form.addErrorMessage(parsed.message || 'Workflow pipeline execution failure.');
                    }
                } catch(err) {
                    g_form.addErrorMessage('An error occurred while processing the server return stream.');
                }
            });
        });
    };

    if (contactId) {
        g_form.getReference('contact', function(con) { openModal(con ? (con.phone || con.mobile_phone || '') : ''); });
    } else if (consumerId) {
        g_form.getReference('consumer', function(cons) { openModal(cons ? (cons.mobile_phone || cons.phone || '') : ''); });
    } else {
        openModal(g_form.getValue('phone') || g_form.getValue('callback_number') || '');
    }
}
